{"code": "import re,ast,copy,math,itertools
h=load_history();pairs=[]
def codeblock(s):
 m=re.search(r'```python\n(.*?)```',s,re.S);return m.group(1) if m else None
def parsed(s):
 try:return ast.parse(s)
 except:return None
for r in h:
 q=r['question'];gold=r['answer'].split('<')
 if r['task']!='ranking' or '## Sample budget (same for all choices)' not in q:continue
 t=re.search(r'- training_steps: (\d+)',q);bs=re.search(r'- batch_size: (\d+)',q)
 if not t or not bs:continue
 T=int(t[1]);B=int(bs[1]);cs=[]
 for c,b in re.findall(r'### Choice ([A-Z])\n(.*?)(?=### Choice|## Your answer|\Z)',q,re.S):
  if '**Model code**' not in b or '**Optimizer**' not in b or '**Loss**' not in b:continue
  mo=codeblock(b.split('**Model code**')[1].split('**Optimizer**')[0]);op=codeblock(b.split('**Optimizer**')[1].split('**Loss**')[0]);lo=codeblock(b.split('**Loss**')[1]);a=parsed(op) if op else None
  if not a or not mo or not lo:continue
  calls=[x for x in ast.walk(a) if isinstance(x,ast.Call) and isinstance(x.func,ast.Attribute) and x.func.attr=='Adagrad']
  if len(calls)!=1:continue
  try:
   vals={x.arg:ast.literal_eval(x.value) for x in calls[0].keywords};lr=vals['lr'];wd=vals.get('weight_decay',0)
  except:continue
  for kw in calls[0].keywords:
   if kw.arg=='weight_decay':kw.value=ast.Constant(0)
  if not any(kw.arg=='weight_decay' for kw in calls[0].keywords):calls[0].keywords.append(ast.keyword(arg='weight_decay',value=ast.Constant(0)))
  key=(ast.dump(parsed(mo)),ast.dump(a),ast.dump(parsed(lo)))
  cs.append((c,key,lr,wd))
 for a,b in itertools.combinations(cs,2):
  if a[1]!=b[1] or a[3]==b[3] or a[0] not in gold or b[0] not in gold:continue
  low,high=sorted((a,b),key=lambda x:x[3]);win=gold.index(low[0])<gold.index(high[0]);delta=2*low[2]*math.sqrt(T)
  pairs.append((r['question_id'],r['epoch'],r['family'],low[0],high[0],low[2],low[3],high[3],T,B,delta,win))
print('all decay-only Adagrad pairs',len(pairs),'wins',sum(p[-1] for p in pairs))
small=[p for p in pairs if p[8]<=1024 and p[10]<=.01 and 0<=p[6]<p[7]<=.001]
print('small',len(small),'wins',sum(p[-1] for p in small),'questions',len(set(p[0] for p in small)))
for p in small:print(p)
print('outside counterexamples',[p for p in pairs if not p[-1]])"}

